import {crystalChart} from "./charts.mjs";
// Original Chinese course notes. Sources are linked for definitions and APIs.
const p=s=>`<p>${s}</p>`;
const eq=(s,n='')=>`<div class="equation">${s}${n?`<small>${n}</small>`:''}</div>`;
const code=s=>`<pre class="tutorial-code"><code>${s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}</code></pre>`;
const note=s=>`<p class="note">${s}</p>`;
const task=(s,target='lab',preset='')=>`<button class="button tutorial-action" data-action="${target}"${preset?` data-preset="${preset}"`:''}>${s}</button>`;
const answer=(q,a)=>`<details class="self-check"><summary>${q}</summary>${p(a)}</details>`;
const frac=(a,b)=>`<span class="fraction"><span>${a}</span><span>${b}</span></span>`;
const table=(heads,rows)=>`<div class="tutorial-table"><table><thead><tr>${heads.map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const flow=items=>'<div class="concept-flow" role="list">'+items.map(([title,detail])=>'<div role="listitem"><b>'+title+'</b><span>'+detail+'</span></div>').join('')+'</div>';
const sections=items=>items.map(([id,title,body])=>({id,title,body}));
export const tutorials={
structure:{minutes:'15–20 分钟',prerequisite:'向量、三维坐标与立方体体积',goal:'区分晶格与基元、原胞与常规晶胞；用几何验证 Si / Al / Ag 的结构。',sections:sections([
 ['picture','把无限晶体装进一个晶胞','<figure class="tutorial-figure">'+crystalChart({a:5.431,elevation:25,azimuth:35,symbol:'Si'})+'<figcaption>Si 常规晶胞中的 8 个等效原子；边界外按平移继续重复。</figcaption></figure>'+p('晶体可以看成一个基元在三个平移方向上重复。晶格矢量 a₁、a₂、a₃ 规定重复的方式，基元中的原子规定每次重复的内容。周期性边界意味着晶胞之外不是空白，而是相邻晶胞的平移副本。')+eq('R = n₁a₁ + n₂a₂ + n₃a₃；　r = R + r<sub>basis</sub>','n₁、n₂、n₃ 为整数；R 是晶格平移，r_basis 是基元中原子的位置。')+p('本课用半开区间 [0,1) 的分数坐标列出一个常规晶胞中的等效原子。边界上的等效原子只列一次。因此，图中的点数可以直接计数，但图中画出的连线并不是每个原子的完整配位壳层。')],
 ['coordinates','从分数坐标得到真实距离',p('分数坐标 f 没有单位。对立方常规晶胞，三条晶格矢量相互垂直且长度均为 a，所以笛卡尔坐标等于 a 乘分数坐标。对于非正交原胞，要用完整晶格矩阵，不能逐项乘一个边长。')+eq('r = f₁a₁ + f₂a₂ + f₃a₃；　V = |a₁ · (a₂ × a₃)| = a³','最后的 a³ 仅用于当前立方常规晶胞。r 和 a 的单位为 Å；V 为 Å³。')+p('Si 的两个最近邻分数坐标之差可取 (¼,¼,¼)。Al / Ag 的 fcc 最近邻之差可取 (0,½,½)。对它们分别求向量长度：')+eq('d<sub>Si</sub> = a√[(¼)² + (¼)² + (¼)²] = √3 a / 4<br>d<sub>fcc</sub> = a√[(½)² + (½)²] = a / √2')+p('例如 a = 5.431 Å 时，Si 的最近邻距离约为 2.352 Å。体积则约为 160.191 Å³。几何精确并不意味着这个 a 已经由能量最小化得到。')],
 ['cells','为什么 Si 有 8 个原子，Al / Ag 有 4 个？',p('fcc 常规晶胞的等效原子数为 8 个角点 × ⅛ + 6 个面心 × ½ = 4。金刚石结构可以从 fcc 出发，为每个晶格点增加相对位移 (¼,¼,¼) 的第二个原子，得到 8 个原子。')+table(['案例','常规晶胞 / 原胞','最近邻配位数'],[['Si · 金刚石','8 / 2','4'],['Al、Ag · fcc','4 / 1','12']])+p('原胞是能通过平移铺满晶体的最小体积单元。fcc 原胞体积为 a³/4，通常不是立方体。ASE 的 bulk 默认给出原胞；cubic=True 切换为常规立方晶胞。两种表示的总能量不能直接比较，应先除以原子数。')],
 ['code','把几何公式对应到代码',code('fractional = np.array([...])   # 无单位的分数坐标\npositions = a * fractional     # Å；只适用于当前立方表示\nnearest = np.sqrt(3)*a/4       # Si\n# fcc Al / Ag: nearest = a / np.sqrt(2)\n# 原生 ASE 环境：bulk("Al", "fcc", a=4.043, cubic=True)')+p('程序先建立原子坐标，再绘制晶胞边与胞内最近邻连线。视角只改变投影，不改变坐标、体积或键长。Python 输出的 CSV 是笛卡尔坐标；图中的原子大小只用于显示，没有表示离子半径。')],
 ['experiment','先预测，再改变晶格常数',p('选择 Si，记下 a、V 与最近邻距离。把 a 增加 1%，预测键长增加 1%，而体积增加 (1.01³ − 1) × 100% ≈ 3.03%。再切换 Al / Ag，检查相同 a 下 fcc 与金刚石结构的最近邻距离是否一致。')+task('进入晶体几何实验')+answer('检查理解：换一个观察角度会改变键长吗？','不会。旋转改变的是投影。周期性最近邻还可能跨过晶胞边界，不能只凭画面里可见的连线数判断配位数。')],
 ['limits','几何结构与电子结构之间还差什么',p('本课没有求能量、受力或电子密度。参考晶格常数只是起始结构。研究应先决定泛函、PAW 数据、基组与 k 点，再通过结构优化或 E(V) 曲线得到平衡结构，并检查其收敛。')+note('Si、Al、Ag 的结构差异适合学习晶胞表示；原子间距与光谱峰位之间不能在这里建立一条未经计算的直接映射。')]
 ])},
convergence:{minutes:'20–25 分钟',prerequisite:'能量单位、数组与相邻差分',goal:'建立可复核的收敛判据，并区分基态能量收敛和目标光谱收敛。',sections:sections([
 ['picture','收敛是一项关于目标量的判断',p('计算用有限基组、有限 k 点和有限空带近似连续或无限的问题。收敛测试问的是：继续增加数值精度后，我关心的量还会变化多少？它不保证所选物理近似正确，也不等于求解器内部的自洽迭代已经停止。')+p('先写下研究目标与允许误差。例如比较结构稳定性时关注每原子能量；比较光谱时可能关注指定能量区间内的峰位、谱重或积分面积。阈值应由研究目的决定，网页中的 2 meV/atom 只是练习值。')],
 ['criterion','一步步建立本课的判据',p('先把不同计算统一为 eV/atom。对升序截断能 Cᵢ 的相邻结果计算绝对差，并将 eV 换成 meV：')+eq('δᵢ = 1000 |Eᵢ − Eᵢ₋₁| ≤ τ','Eᵢ 是每原子能量，单位 eV/atom；τ 是容差，单位 meV/atom。')+p('本课把 Cᵢ 标记为候选点，要求 δᵢ 及所有已采样的后续相邻差都小于等于 τ，而且 i 不能是最后一个点。这样会拒绝一次偶然接近后又明显变化的结果。')+eq('候选 i：δⱼ ≤ τ 对所有已采样 j ≥ i 成立，且 i &lt; N − 1')+note('这个规则只检验已采样的相邻变化，不保证相对无限基组的误差小于 τ。许多小变化累积起来仍可产生较大漂移；可补充与最高精度参考值的比较，并继续增加采样。')],
 ['basis','截断能、k 点和空带分别控制什么',p('平面波基组保留动能不超过截断能的波矢。更高截断能允许更短的空间波长；k 点则用于采样布里渊区。它们控制不同近似，不能相互替代。')+eq('ℏ² |k + G|² / (2m) ≤ E<sub>cut</sub>','k 是第一布里渊区中的采样点，G 是倒格矢。')+table(['参数','主要控制','建议比较的量'],[['基态 PW 截断能','波函数的基组精度','能量、受力、后续光谱'],['k 点密度','布里渊区积分','能量、峰位、峰形'],['空带数 nbands','响应中的跃迁空间','目标区间内的谱重'],['响应 ecut','介电矩阵的 G 空间大小','局域场修正后的光谱'],['展宽 η / 金属占据展宽','频谱分辨率 / 费米面采样','分别测试；二者不是同一个参数']])],
 ['materials','为什么三种材料不能共用一份“已收敛参数”',p('Si、Al、Ag 的电子结构不同，不能因为同样使用 8×8×8 k 点，就认为精度相同。对于金属，费米能附近的占据与 k 点采样需要特别关注。包含更多参与响应的能带时，也必须保证可用的空态足够。')+p('正确的比较是让每种材料分别达到相同的目标误差，再比较物理结果。网页的能量数组是单独编写的合成教学数据，既不属于 Si，也不代表 Al 或 Ag 的收敛成本。')],
 ['code','读懂筛选候选点的代码',code('diffs = np.abs(np.diff(energies)) * 1000\nfor i in range(1, len(energies) - 1):\n    # diffs[i-1] 对应 E[i] 与 E[i-1] 的差\n    if np.all(diffs[i-1:] <= tolerance):\n        candidate = cutoffs[i]\n        break')+p('第一点没有前一个能量，因此不产生相邻差；最后一点没有更高精度点复核，因此不直接作为候选。替换数组时，必须保持截断能和能量一一对应，使用相同结构、泛函和每原子归一化。')],
 ['experiment','把平滑曲线和收敛证据分开',p('依次试用 0.5、2 和 5 meV/atom。当前数据在 2 meV/atom 下得到 450 eV，在 0.5 meV/atom 下没有可复核候选点。然后修改一个中间能量，观察筛选结果。')+task('检查合成数据的收敛')+answer('检查理解：增大光谱展宽让曲线更平滑，能说明 k 点够密吗？','不能。展宽可能掩盖采样噪声。应在固定展宽下加密 k 点，再独立检查展宽对结论的影响。')+p('正式记录应包含参数、目标量、误差指标、运行成本与参考计算。若要宣称光谱收敛，应同时展示目标区间内的多条光谱，而不只展示一张总能量表。')]
 ])},
optics:{minutes:'25–35 分钟',prerequisite:'复数、简谐运动与电磁波',goal:'从电子响应推导 ε、吸收系数与损失函数，理解 Si / Al / Ag 案例各自说明的机制。',sections:sections([
 ['picture','外场、极化与复介电函数',flow([['外电场','弱扰动 E(t)'],['电子响应','位移与极化 P(t)'],['复介电函数','相位与耗散'],['可比较的光谱','ε₂、α 与损失函数']])+p('弱外场使电子发生位移，诱导极化。在线性、非磁性、均匀的介质近似下，频域中可以用介电函数描述响应。这里采用 exp(−iωt) 的时间约定，正的虚部对应被动介质的耗散。')+eq('D = ε₀E + P = ε₀ε(ω)E；　ε = ε₁ + iε₂','此处 E 是电场；下文改用能量 E = ℏω 时会明确说明。ε 为相对介电函数，无量纲。')+p('ε₁ 影响相位与色散，ε₂ 描述介电损耗。它们不是两套彼此任意独立的函数：因果响应会约束实部与虚部之间的关系。实验台的模型用同一个复函数同时生成二者。')],
 ['lorentz','从受迫振子得到 Lorentz 模型',p('先把受束缚电子近似为带阻尼的谐振子。m 为电子有效的惯性参数，γ 为阻尼率，ω₀ 为共振角频率。电子电荷为 −e，ℰ₀ 为电场振幅：')+eq('mẍ + mγẋ + mω₀²x = −eℰ₀e<sup>−iωt</sup>')+p('令位移也按 exp(−iωt) 变化，把时间导数替换为 −iω，得到振幅。若每单位体积有 N 个响应电子，则 P = −Nex。代入 D 的定义后：')+eq('ε(ω) = 1 + '+frac('Ne² / (ε₀m)','ω₀² − ω² − iγω'))+p('网页横轴使用光子能量 E = ℏω。定义 E₀ = ℏω₀、Γ = ℏγ，并把分子写成强度 S 后，可直接用 eV 计算：')+eq('ε(E) = 1 + '+frac('S','E₀² − E² − iΓE'),'E、E₀、Γ 为 eV；S 为 eV²。')+p('Si 案例用该模型说明束缚电子共振。它没有 Si 的能带、跃迁矩阵元或声子辅助过程，因此不能给出硅的真实吸收边。改变 Γ 可以研究峰宽变化，改变 S 可以研究响应强度与损失峰位置的关系。')+task('进入 Lorentz 实验','lab','Si')],
 ['drude','自由电子与带间跃迁：Al 和 Ag 案例',p('把回复力设为零，令 ω₀ = 0，就得到 Drude 项。再把束缚响应与自由电子响应相加，可构成 Drude–Lorentz 教学模型：')+eq('ε(E) = 1 − '+frac('E<sub>p</sub>²','E² + iΓE')+' + '+frac('S','E₀² − E² − iΓE'),'Eₚ = ℏωₚ；本课为简化比较，两项使用同一个 Γ。真实拟合可以有多个振子和不同阻尼。')+p('Al 案例仅保留 Drude 项；Ag 案例再加一个 Lorentz 项，观察带间响应对集体激发的影响。这里的 Si / Al / Ag 光学参数均是编写者选择的机制示意值，未经测量或第一性原理拟合。')+table(['模型预设','E₀ / Γ / S / Eₚ','作用'],[['Si','3.4 / 0.35 / 12 / 0','束缚共振'],['Al','3.4 / 0.30 / 0 / 15','自由电子；S=0 时 E₀ 不起作用'],['Ag','4.5 / 0.35 / 60 / 9','自由电子叠加带间机制']])+note('金属 Drude 项在零能量处奇异。预览和 Python 从 0.05 eV 开始，不把静态金属响应当成普通有限介电常数。')+task('比较三种机制','compare')],
 ['observables','从 ε 推导 n、κ 和吸收系数',p('在当前非磁性、局域介质近似下，复折射率 n + iκ 的平方等于 ε。展开实部与虚部，得到 n² − κ² = ε₁ 和 2nκ = ε₂。取被动介质中非负的 n、κ：')+eq('n = √[(|ε| + ε₁)/2]；　κ = √[(|ε| − ε₁)/2]')+p('沿 z 传播的电场振幅按 exp(−ωκz/c) 衰减；光强与振幅平方成正比，所以 I(z) = I(0)exp(−αz)，并得到：')+eq('α = 2ωκ/c = 2Eκ/(ℏc)','ℏc ≈ 197.3269804 eV·nm，因此 E 用 eV 时，α 的单位为 nm⁻¹。')+p('ε₂ 没有单位，α 有倒长度单位，两者不能共用“吸收系数”的标签。比较材料时应选择相同物理量、单位和能量范围；归一化后的峰高也不能再用于比较绝对吸收强度。')],
 ['loss','为什么 EELS 峰不一定在 ε₂ 最大处',p('对复数求逆，把分子分母同时乘以共轭，得到损失函数：')+eq('1/ε = '+frac('ε₁ − iε₂','ε₁² + ε₂²')+'；　L = −Im(1/ε) = '+frac('ε₂','ε₁² + ε₂²'))+p('当 ε₁ 接近零且 ε₂ 足够小时，损失函数可能出现强峰。ε₂ 很大时会增加分母并引入阻尼，所以“介电损耗最大”与“损失函数最大”不是同一个条件。本课画的是 q→0 模型损失函数；有限动量转移的 EELS 必须另做 q 相关的计算。')+answer('检查理解：能把模型 Ag 曲线中的峰直接写成银的实验峰吗？','不能。机制模型只能检验公式和参数间的关系。真实 Ag 需要能带、跃迁与数值收敛信息；应使用可追溯的实际计算或实验数据。')],
 ['code','对照代码，完成一组可复现的比较',code('epsilon = (1 + strength/(e0**2-energy**2-1j*gamma*energy)\n           - wp**2/(energy**2+1j*gamma*energy))\nloss = -np.imag(1/epsilon)\nkappa = np.sqrt(np.maximum(0, (np.abs(epsilon)-epsilon.real)/2))\nalpha = 2*energy*kappa/197.3269804')+p('先固定 Si 的 E₀、S，只改变 Γ，再运行 Python 检查峰宽。然后选择 Al，检查弱阻尼时损失峰是否靠近 Eₚ。最后选择 Ag，把 S 从 60 减到 0，观察带间机制消失后的变化。每次运行前都把参数写入代码。')+p('材料对比区使用明确列出的默认模型参数，不跟随上方单材料滑块。三条曲线共享 0.05–25 eV 的 501 点网格，支持 ε₂、L、α 的切换，并可把同一比较生成 Python 与 CSV。')+task('进入光谱与材料对比实验')]
 ])},
data:{minutes:'20–25 分钟',prerequisite:'CSV、复介电函数与基本绘图',goal:'正确识别 GPAW 数据，比较局域场与材料差异，并记录结论的适用范围。',sections:sections([
 ['picture','先确认一条曲线是谁的结果',p('拿到数据文件，先确认来源：作者编写的合成练习、原生 GPAW 计算，还是实验测量。文件名含 Si 或 Ag 不能证明材料身份；五列数字本身也不会告诉你温度、晶格常数或泛函。')+p('网站保留原始数值，不自动平滑、归一化、移动峰位或填补缺失点。缺少计算条件时，可以描述曲线形状，但不能据此宣称数值已经收敛或与实验一致。')],
 ['columns','逐列读取 df.csv',table(['列','含义','单位'],[['1','能量 E','eV'],['2 / 3','无局域场校正的 Re ε / Im ε','无量纲'],['4 / 5','有局域场校正的 Re ε / Im ε','无量纲']])+p('导入器支持 # 注释和一行以 energy、omega 等开头的文字表头；能量必须严格递增，数值必须有限。本页拒绝重复能量、缺列、NaN 与三列 EELS 文件，避免画出外观合理而含义错误的结果。')+code('data = np.loadtxt("df.csv", delimiter=",")\nenergy = data[:, 0]\nepsilon_lf = data[:, 3] + 1j * data[:, 4]\nloss_lf = -np.imag(1 / epsilon_lf)')+note('三列 eels.csv 一般保存能量、无局域场损失、有局域场损失，不能冒充五列 df.csv。若使用带文字表头的原始文件，需先按表头设置读取方式；网站会为内置 Python 生成规范化输入。')],
 ['local-field','宏观响应为什么需要矩阵求逆',p('晶胞内部的电子密度不均匀，外部扰动会激发不同倒格矢分量之间的耦合。介电响应因此一般是 G、G′ 索引的矩阵。忽略这些微观耦合与把它们纳入宏观平均，会得到不同结果。')+eq('ε<sub>M,LF</sub> = '+frac('1','(ε<sup>−1</sup>)₀₀')+'；　ε<sub>M,NLF</sub> = ε₀₀')+p('顺序很关键：先对整个矩阵求逆，再取 00 分量，再取倒数。一个矩阵的逆的 00 元素，一般不等于原矩阵 00 元素的倒数。因此 LF 与 NLF 的差异来自响应耦合，不能用随意移动一条曲线来代替。')],
 ['compare','怎样公平比较 Si、Al、Ag',p('先在各自的原生脚本中计算并收敛，再把三个 df.csv 加入对比区，为每个文件选择材料标签。标签由你指定，网页不会从五列数据自动识别材料。')+p('对比区使用有局域场列，支持 ε₂、L 和 α。曲线只显示各文件共同覆盖的能量范围；保留各自采样点，不插值、不归一化。若能量范围不重叠，应重新导出可比的范围。')+table(['记录项','为什么需要'],[['结构、晶格、方向与动量转移','确保比较的是明确的物理状态'],['泛函、PAW 数据与 GPAW 版本','解释方法与版本差异'],['k 点、空带与两种截断能','提供数值精度证据'],['占据展宽与响应展宽','避免把分辨率变化误判为材料差异']])+note('网页无法验证导入文件的计算方法与收敛性。材料不同可以使用不同数值参数，但应达到可比的误差标准。')+task('导入并比较材料结果')],
 ['code','把数据转成物理量',p('取有局域场的复介电函数后，按第三课公式计算损失函数与吸收系数。对于被动介质的正常吸收区，ε₂ 应非负；出现负数时先检查约定、频率范围和文件内容，不应直接取绝对值掩盖问题。')+code('re, im = data[:, 3], data[:, 4]\nloss = im / (re**2 + im**2)\nkappa = np.sqrt(np.maximum(0, (np.hypot(re, im) - re)/2))\nalpha = 2*energy*kappa/197.3269804')+p('峰位是离散网格上的采样最大值。如果峰正好落在能量窗口的边界，只能说窗口内最大值出现在边界，不能推断完整峰已被包含。更密网格不自动弥补 k 点不足。')],
 ['exercise','练习：写一段有证据的结果说明',p('先用合成示例熟悉导入和运行，再替换为真实 df.csv。记录文件名、数据来源、能量范围、是否启用局域场，以及观测到的峰位变化。将图像和输入文件一起保存。')+answer('检查理解：只有 df.csv，能否判断 Ag 比 Si 更容易收敛？','不能。CSV 没有测试序列和计算成本。需要为每种材料提供参数逐项变化的结果、误差指标与运行记录。')+p('合成示例故意让两条曲线不同，以练习格式与分析流程；该差异不是 GPAW 局域场效应的数值预测。材料模型对比和真实数据对比使用不同入口，避免混淆。')]
 ])},
gpaw:{minutes:'25–35 分钟',prerequisite:'前四课、Python 脚本与终端操作',goal:'读懂 Si / Al / Ag 的原生计算流程，建立计算、记录、收敛和回传数据的闭环。',sections:sections([
 ['pipeline','从结构到光谱的四个环节',flow([['原子结构','晶胞与周期性'],['基态','自洽电子密度'],['空态与响应','屏蔽及跃迁'],['结果验证','CSV 与收敛对比']])+p('网页提供可下载脚本；完整 GPAW 在带原生数值库和 PAW 数据的环境中运行。Windows 用户可以选择 WSL，或使用学校集群。浏览器里的 NumPy / Matplotlib 实验不能替代原生 GPAW。')+eq('结构 → 自洽基态 → 空态与波函数 → 介电响应 → CSV')+p('先构建周期性原子结构，再求基态密度与 Kohn–Sham 态。响应需要占据态与空态之间的跃迁，因此仅得到基态能量并不足够。保存波函数后，才能让响应计算读取所需信息。')+p('PAW 用原子附近的重构信息连接平滑的辅助波函数与全电子性质。数据集属于计算定义的一部分，应与程序版本一起记录，不能只保存一张最终光谱图。')],
 ['ground','逐段理解基态代码',code('atoms = bulk(symbol, crystal, a=a)\natoms.calc = GPAW(mode=PW(cutoff), xc="LDA",\n                  kpts=(k, k, k),\n                  occupations=FermiDirac(0.05 if metal else 0.001))\nenergy = atoms.get_potential_energy()')+p('bulk 建立原胞：Si 为 2 原子，Al / Ag 的 fcc 原胞为 1 原子。PW 截断能控制基态基组；kpts 控制布里渊区采样；FermiDirac 控制占据展宽。调用 get_potential_energy 才会触发自洽计算。')+p('脚本使用 LDA 和固定起始晶格常数以便追踪教程流程，不意味着它们适合所有研究目标。金属占据展宽选择 0.05 eV，Si 使用 0.001 eV，都是需要复核的起点。')],
 ['response','空带、波函数和介电响应',code('calc.diagonalize_full_hamiltonian(nbands=bands)\ncalc.write(stem + ".gpw", mode="all")\ndf = DielectricFunction(calc=stem + ".gpw",\n    frequencies={"type": "nonlinear", "domega0": 0.05},\n    eta=0.1, ecut=50, nbands=bands,\n    intraband=metal, rate=0.1)\ndf.get_dielectric_function(direction="x", filename="df.csv")')+p('对角化得到后续求和需要的空态，mode="all" 保存波函数。响应中的 ecut=50 eV 控制介电矩阵展开，与前面的基态 PW 截断能不同。eta 是响应展宽；rate 是金属带内 Drude 散射率的能量参数。')+p('从物理上看，响应把不同占据态与空态的跃迁贡献加总，再处理屏蔽。常用 RPA 忽略响应交换关联核；它不自动包含完整的电子–空穴吸引。与实验比较时，带隙低估和激子效应都可能影响结论。')+note('最新官方示例对带内项显式设置 rate。本页也显式传入它。不同 GPAW 版本可能有接口差异；原生脚本经语法和结构检查，未在本站制作环境运行 GPAW。')],
 ['metals','Al / Ag 额外计算有限 q 的 EELS',p('选择金属后，脚本开启带内贡献，并额外输出三列 eels.csv。Si 案例只输出五列介电函数文件。动量转移要连接基态 k 点网格上的两个点：')+eq('q<sub>c</sub> = (1/k, 0, 0)','这是倒格矢基底下的分数坐标，不是直接以 Å⁻¹ 表示的矢量。')+code('if metal:\n    df.get_eels_spectrum(q_c=[1.0/k, 0, 0], filename="eels.csv")')+p('若改变 k，这个最小可用 q 也跟着改变。因此用它测试 k 点收敛时，会同时改变物理动量转移。正式研究应选定共同可表示的 q，或明确研究的是随 q 改变的色散。q→0 模型曲线也不能与有限 q 的 EELS 无条件等同。')],
 ['run','第一次运行的实际步骤',p('依照官方安装说明配置 GPAW、ASE 和 PAW 数据，在终端运行 gpaw info 与 gpaw test。然后为每种材料建立独立目录，避免 df.csv 被另一次运行覆盖。')+code('mkdir si_run\ncd si_run\n# 把下载的 gpaw_si.py 放在这里\npython gpaw_si.py\n# 在另一个目录中运行 gpaw_al.py 或 gpaw_ag.py')+p('检查基态日志是否正常收敛、响应日志是否正常结束，再把 df.csv 导入第四课。记录总耗时与内存。如果需要 MPI，遵照所在集群的作业系统和官方并行启动方式，不在登录节点提交大型生产计算。')+task('选择材料并生成原生脚本')],
 ['reproduce','把练习升级为可复现研究',p('依次收敛基态截断能与 k 点，再检查空带、响应截断能和目标光谱。高质量光谱可能需要在收敛密度上使用更密 k 点的固定密度计算，当前最小脚本没有自动完成这组研究。')+table(['保存内容','用途'],[['原始脚本与全部参数','复现计算输入'],['GPAW / ASE / PAW 版本','确定实现与数据集'],['结构、方向、q 和单位','确定物理对象'],['日志与收敛对比','评估数值可信度'],['原始 CSV 与分析脚本','追踪图像和结论来源']])+answer('检查理解：脚本没有报错，是否就可以把光谱作为论文结论？','还不够。还需确认收敛、物理近似、输入结构与目标实验相容，并保留误差与版本记录。成功运行只说明这次流程完成。')+p('后续的 MoS₂ 模块将单独处理二维极化率、真空厚度、库仑截断和激子，避免把三维体材料的默认设置直接套到二维系统。')]
 ])}
};
export function tutorialHTML(id,sources){
 const t=tutorials[id];
 return `<div class="tutorial-layout"><nav class="tutorial-toc" aria-label="本课教程目录"><div class="eyebrow">THEORY TUTORIAL</div><strong>本课目录</strong>${t.sections.map((s,i)=>`<a href="#theory-${id}-${s.id}"><span>${String(i+1).padStart(2,'0')}</span>${s.title}</a>`).join('')}<a href="#theory-${id}-sources">参考资料</a></nav><article class="tutorial-article"><div class="tutorial-overview"><span class="reading-time">建议学习 ${t.minutes}</span><h2>本课你将学会</h2>${p(t.goal)}<p class="prerequisite"><b>前置知识</b>　${t.prerequisite}</p>${task('开始本课实验')}</div>${t.sections.map((s,i)=>`<section class="tutorial-section" id="theory-${id}-${s.id}"><div class="section-index">${String(i+1).padStart(2,'0')}</div><h2>${s.title}</h2>${s.body}</section>`).join('')}<section class="tutorial-section" id="theory-${id}-sources"><h2>参考资料与下一步</h2><p>中文讲解与练习为独立编写。公式与 API 可在下列官方资料核对；光学预设是教学模型，不是官方数据。资料核对：2026-10-02。</p><div class="source-list">${sources.map(s=>`<a class="source-link" href="${s[0]}" target="_blank" rel="noopener noreferrer">${s[1]}<small>${s[2]}</small></a>`).join('')}</div>${task('带着问题回到实验')}</section></article></div>`;
}
